#include <bits/stdc++.h>

using namespace std;

int main() {
    // your code goes here
    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;

        int total = 3 * n;
        vector < long long > arr(total + 1), preSum(total + 1, 0);

        for (int i = 1; i <= total; i++) {
            cin >> arr[i];
        }

        sort(arr.begin() + 1, arr.end(), greater < long long > ());

        for (int i = 1; i <=total; i++) {
            preSum[i] = preSum[i - 1] + arr[i];
        }

        long long ans = 0;

        for (int i = 0; i <= n; i++) {
            int l = 0, r = n - i;

            auto f = [ & ](int y) -> long long {
                int u = i + 2 * y;
                int v = 3 * n - 2 * i - y;

                return 2 * preSum[i] + preSum[u] + 3 * preSum[v];
            };

            while (l < r) {
                int mid = l + (r - l) / 2;
                if (f(mid) <= f(mid + 1)) {
                    l = mid + 1;
                } else {
                    r = mid;
                }
            }
            ans = max(ans, f(l));
        }

        cout << ans << '\n';

    }
    return 0;
}
